package consensus

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
)

// 交易被拒绝的具体原因。
const (
	// ReasonBadSignature 签名非法或与发送者公钥不匹配。
	ReasonBadSignature = "bad-signature"
	// ReasonExpired 交易在提交时已经到期（到期轮次不大于当前轮次）。
	ReasonExpired = "tx-expired"
	// ReasonOldSequence 交易序号不大于该发送者已确认序号。
	ReasonOldSequence = "sequence-already-confirmed"
	// ReasonDuplicate 池中已有完全相同的交易（同一发送者、同一序号、同一标识）。
	ReasonDuplicate = "duplicate-transaction"
	// ReasonLowFee 池中同发送者同序号已有交易，但新交易费用没有严格更高。
	ReasonLowFee = "fee-not-higher"
	// ReasonPoolFull 交易池已满，且新交易不足以挤出任何可淘汰的排队交易。
	ReasonPoolFull = "pool-full"
	// ReasonNotValidator 投票者不在验证者名单内。
	ReasonNotValidator = "not-validator"
	// ReasonWrongRound 投票轮次与当前轮次不一致。
	ReasonWrongRound = "wrong-round"
	// ReasonWrongBlock 投票区块标识与当前提议区块标识不一致。
	ReasonWrongBlock = "wrong-block-id"
	// ReasonNoProposal 当前轮次尚不存在提议。
	ReasonNoProposal = "no-proposal"
	// ReasonAlreadyVoted 该验证者本轮已投过其他候选，不能改投。
	ReasonAlreadyVoted = "already-voted"
	// ReasonUnknownRound 查询的轮次不存在（为 0 或尚未到达）。
	ReasonUnknownRound = "unknown-round"
)

// TxStatus 表示一笔交易相对于本节点当前状态的状态。
type TxStatus string

const (
	// StatusQueued 在交易池中等待打包。
	StatusQueued TxStatus = "queued"
	// StatusProposed 已进入当前轮次提议，等待投票。
	StatusProposed TxStatus = "proposed"
	// StatusConfirmed 已被某个确认块包含。
	StatusConfirmed TxStatus = "confirmed"
	// StatusReplaced 在交易池中被同发送者同序号、费用严格更高的交易替换。
	StatusReplaced TxStatus = "replaced"
	// StatusExpired 在进入新轮次时因到期轮次不大于当前轮次而失效。
	StatusExpired TxStatus = "expired"
	// StatusDropped 在交易池满时被费用更高的新交易挤出。
	StatusDropped TxStatus = "dropped"
)

// DropReasonPoolCapacity 是交易被挤出交易池时记录的原因：池容量限制。
const DropReasonPoolCapacity = "pool-capacity"

// Transaction 是一笔带 Ed25519 签名的交易。
type Transaction struct {
	// Sender 发送者公钥（Ed25519 原始 32 字节公钥）。
	Sender []byte `json:"sender"`
	// Sequence 正整数序号。
	Sequence uint64 `json:"sequence"`
	// Content 交易内容，可为任意字节。
	Content []byte `json:"content"`
	// Fee 非负整数费用。
	Fee uint64 `json:"fee"`
	// Expiry 到期轮次：进入不小于该值的轮次时交易失效。
	Expiry uint64 `json:"expiry"`
	// Signature 对 SigningBytes 的 Ed25519 签名。
	Signature []byte `json:"signature"`
}

// signDoc 是签名与稳定编码使用的规范结构。字段按名字典序声明，
// Go 的 JSON 编码按结构体字段顺序输出，故序列化结果即公开的签名编码。
type signDoc struct {
	Content  string `json:"content"`
	Expiry   uint64 `json:"expiry"`
	Fee      uint64 `json:"fee"`
	Sender   string `json:"sender"`
	Sequence uint64 `json:"sequence"`
}

func docFromTx(tx *Transaction) signDoc {
	return signDoc{
		Sender:   base64.StdEncoding.EncodeToString(tx.Sender),
		Sequence: tx.Sequence,
		Content:  base64.StdEncoding.EncodeToString(tx.Content),
		Fee:      tx.Fee,
		Expiry:   tx.Expiry,
	}
}

// SigningBytes 返回交易的公开稳定签名编码：
// canonical JSON（UTF-8、无空白、字段按名字典序）外再包一层固定前缀。
// 任何语言按相同 JSON 规则即可重建并验签。
func SigningBytes(sender ed25519.PublicKey, sequence uint64, content []byte, fee, expiry uint64) []byte {
	tx := &Transaction{Sender: sender, Sequence: sequence, Content: content, Fee: fee, Expiry: expiry}
	raw, _ := json.Marshal(docFromTx(tx))
	out := make([]byte, 0, len("consensus-lab-tx-v1\n")+len(raw))
	out = append(out, []byte("consensus-lab-tx-v1\n")...)
	out = append(out, raw...)
	return out
}

// SigningBytes 返回该交易待签名的字节。
func (tx *Transaction) SigningBytes() []byte {
	return SigningBytes(tx.Sender, tx.Sequence, tx.Content, tx.Fee, tx.Expiry)
}

// Sign 使用发送者私钥填写 Signature。
func (tx *Transaction) Sign(priv ed25519.PrivateKey) {
	tx.Signature = append([]byte(nil), ed25519.Sign(priv, tx.SigningBytes())...)
}

// NewTransaction 构造并用 priv 签名一笔交易。
func NewTransaction(priv ed25519.PrivateKey, sequence uint64, content []byte, fee, expiry uint64) *Transaction {
	pub := priv.Public().(ed25519.PublicKey)
	tx := &Transaction{
		Sender:   append([]byte(nil), pub...),
		Sequence: sequence,
		Content:  append([]byte(nil), content...),
		Fee:      fee,
		Expiry:   expiry,
	}
	tx.Sign(priv)
	return tx
}

// Verify 校验公钥长度、签名长度以及签名是否有效。
func (tx *Transaction) Verify() bool {
	if len(tx.Sender) != ed25519.PublicKeySize || len(tx.Signature) != ed25519.SignatureSize {
		return false
	}
	return ed25519.Verify(ed25519.PublicKey(tx.Sender), tx.SigningBytes(), tx.Signature)
}

// ID 返回交易标识：规范 JSON 字段（含签名）的 SHA-256 十六进制摘要。
// 该规则公开稳定，同字节内容恒有同标识。
func (tx *Transaction) ID() string {
	type txDoc struct {
		Content   string `json:"content"`
		Expiry    uint64 `json:"expiry"`
		Fee       uint64 `json:"fee"`
		Sender    string `json:"sender"`
		Sequence  uint64 `json:"sequence"`
		Signature string `json:"signature"`
	}
	raw, _ := json.Marshal(txDoc{
		Sender:    base64.StdEncoding.EncodeToString(tx.Sender),
		Sequence:  tx.Sequence,
		Content:   base64.StdEncoding.EncodeToString(tx.Content),
		Fee:       tx.Fee,
		Expiry:    tx.Expiry,
		Signature: base64.StdEncoding.EncodeToString(tx.Signature),
	})
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// SenderHex 返回发送者公钥的十六进制串，便于按账户查询。
func (tx *Transaction) SenderHex() string {
	return hex.EncodeToString(tx.Sender)
}

// Vote 是验证者对某一轮某区块标识的投票。
type Vote struct {
	Validator []byte `json:"validator"`
	Round     uint64 `json:"round"`
	BlockID   string `json:"block_id"`
}

// BlockID 是由轮次、前块标识与交易顺序确定的区块标识。
// 对规范文档（轮次、高度、前块标识、按顺序排列的交易标识）取 SHA-256。
func BlockID(round, height uint64, prevID string, txIDs []string) string {
	type blockDoc struct {
		Round        uint64   `json:"round"`
		Height       uint64   `json:"height"`
		PreviousID   string   `json:"previous_id"`
		Transactions []string `json:"transactions"`
	}
	ids := txIDs
	if ids == nil {
		ids = []string{}
	}
	raw, _ := json.Marshal(blockDoc{Round: round, Height: height, PreviousID: prevID, Transactions: ids})
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// Block 是一条连续的确认历史记录。
type Block struct {
	Height     uint64   `json:"height"`
	Round      uint64   `json:"round"`
	ID         string   `json:"id"`
	PreviousID string   `json:"previous_id"`
	TxIDs      []string `json:"tx_ids"`
}

// TxInfo 是一笔交易的查询结果。
type TxInfo struct {
	// ID 交易标识。
	ID string
	// Status 当前状态。
	Status TxStatus
	// Tx 交易内容（历史记录中同样保留完整字节）。
	Tx *Transaction
	// BlockHeight 已确认时所在区块高度；其他状态为 0。
	BlockHeight uint64
	// BlockID 已确认时所在区块标识。
	BlockID string
	// ReplacedBy 已替换时的新交易标识。
	ReplacedBy string
	// DropReason 被挤出时的原因（pool-capacity）；其他状态为空。
	DropReason string
	// DropRound 被挤出发生的轮次；其他状态为 0。
	DropRound uint64
	// Note 仅用于待处理交易："waiting-vote"（已提议，等待投票）或 "waiting-pack"（池内，等待打包）。
	Note string
}

// AccountInfo 是按账户查询的结果。
type AccountInfo struct {
	Sender string
	// ConfirmedSequence 已确认序号，初值为 0。
	ConfirmedSequence uint64
	// Pending 该账户全部待处理交易（池内排队 + 已提议），按序号升序。
	Pending []*TxInfo
	// Gap 因序号缺口等待时，最早缺少的序号；无缺口为 0。
	Gap uint64
}

// RejectError 描述一次提交或投票被拒绝的具体原因。
type RejectError struct {
	Reason string
	Detail string
}

func (e *RejectError) Error() string {
	if e.Detail == "" {
		return e.Reason
	}
	return fmt.Sprintf("%s: %s", e.Reason, e.Detail)
}

func reject(reason, format string, args ...any) error {
	return &RejectError{Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

// 示例：同一发送者在相同序号上，用一笔费用更高的有效签名交易替换排队中的旧交易。
//
// 流程：提交序号 1、费用 5 的原交易 -> 演示费用不严格更高的替换被 fee-not-higher
// 拒绝 -> 提交费用 9 的新交易完成替换，查询旧记录（replaced）、新交易（queued）
// 与账户队列（waiting-pack、缺口 0）-> 产生本地提议，交易列表只含新交易，
// 新交易进入等待投票 -> 演示提议冻结后再替换被 tx-in-proposal 拒绝，
// 冻结的提议与原有替换关联均不改变。
//
// 运行：go run ./examples/fee-replacement
package main

import (
	"bytes"
	"crypto/ed25519"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/bengzyyys/consensus-lab/consensus"
)

// check 处理正常调用的错误：任何非预期失败都直接终止演示。
func check(err error) {
	if err != nil {
		log.Fatalf("unexpected error: %v", err)
	}
}

// demoKey 由固定字节派生演示密钥，使示例输出可复现；
// 真实应用应使用 crypto/rand 随机生成并妥善保管私钥。
func demoKey(b byte) ed25519.PrivateKey {
	return ed25519.NewKeyFromSeed(bytes.Repeat([]byte{b}, ed25519.SeedSize))
}

// short 截断长标识便于对照阅读；标识本身均来自实际返回值。
func short(id string) string {
	if len(id) > 16 {
		return id[:16] + "…"
	}
	return id
}

// expectReject 提交 tx 并断言它恰好被 reason 拒绝。
// 提交成功或返回其他原因都属于演示失败：立即终止，不继续输出任何成功结果。
func expectReject(n *consensus.Node, reason, label string, tx *consensus.Transaction) {
	res, err := n.Submit(tx)
	var rej *consensus.RejectError
	switch {
	case errors.As(err, &rej) && rej.Reason == reason:
		fmt.Printf("%s被拒绝（预期）：%v\n", label, rej)
	case err != nil:
		log.Fatalf("%s出现预期外的错误（应为 %s）：%v", label, reason, err)
	default:
		log.Fatalf("%s被意外接受（应被 %s 拒绝）：%+v", label, reason, res)
	}
}

func main() {
	log.SetFlags(0)

	// 四名验证者与一个发送账户。
	validatorKeys := make([]ed25519.PrivateKey, 4)
	validators := make([][]byte, 4)
	for i := range validatorKeys {
		validatorKeys[i] = demoKey(byte(i + 1))
		validators[i] = append([]byte(nil), validatorKeys[i].Public().(ed25519.PublicKey)...)
	}
	senderKey := demoKey(0x51)
	senderPub := senderKey.Public().(ed25519.PublicKey)

	// 每次运行都在新的临时状态目录建立节点，程序退出时删除；
	// 固定种子与固定演示密钥使交易、区块标识等输出可复现。
	dir, err := os.MkdirTemp("", "consensus-demo-*")
	check(err)
	defer os.RemoveAll(dir)

	n, err := consensus.New(dir, consensus.Config{
		Seed:           []byte("fee-replacement-demo"),
		Validators:     validators,
		MaxTxsPerBlock: 2,
	})
	check(err)
	fmt.Printf("节点已建立：轮次 %d，单块上限 2，验证者 4 名（状态保存在新的临时目录，退出时删除）\n",
		n.CurrentRound())

	// 原交易：同一发送者、序号 1、费用 5、到期轮次 100（演示期间不会到达）。
	txOld := consensus.NewTransaction(senderKey, 1, []byte("sender: fee 5"), 5, 100)
	resOld, err := n.Submit(txOld)
	check(err)
	oldID := resOld.TxID
	fmt.Printf("\n已提交原交易（序号 1，费用 5，到期轮次 100）：%s\n", oldID)

	// 误用一（替换之前）：同发送者同序号、内容不同但费用仍为 5 的另一笔有效签名交易。
	// 加费要求费用“严格更高”，故以 fee-not-higher 拒绝；被拒交易不留记录，原交易继续排队。
	txEqualFee := consensus.NewTransaction(senderKey, 1, []byte("sender: another fee 5 body"), 5, 100)
	fmt.Println("\n—— 替换前的误用：同序号、不同内容、费用仍为 5 ——")
	expectReject(n, consensus.ReasonLowFee, "同序号等费交易", txEqualFee)
	if _, err := n.Tx(txEqualFee.ID()); err != nil {
		var rej *consensus.RejectError
		if !(errors.As(err, &rej) && rej.Reason == consensus.ReasonUnknownTx) {
			log.Fatalf("被拒交易应不留记录，查询实际返回：%v", err)
		}
		fmt.Printf("被拒绝的交易不留记录（按其标识查询返回 %s）\n", consensus.ReasonUnknownTx)
	} else {
		log.Fatal("被 fee-not-higher 拒绝的交易不应留下记录")
	}
	infoOld, err := n.Tx(oldID)
	check(err)
	fmt.Printf("原交易继续排队：状态=%s\n", infoOld.Status)

	// 合法的加费替换：在相同序号 1 上提交另一笔有效签名交易，费用提高到 9，
	// 到期轮次仍为 100。这只是池内同一序号位置的新旧交替，不是确认。
	txNew := consensus.NewTransaction(senderKey, 1, []byte("sender: fee 9 replacement"), 9, 100)
	resNew, err := n.Submit(txNew)
	check(err)
	newID := resNew.TxID
	if resNew.ReplacedID != oldID {
		log.Fatalf("提交结果的替换关联 = %q，应为原交易 %s", resNew.ReplacedID, oldID)
	}
	if resNew.EvictedID != "" {
		log.Fatalf("加费替换不应挤出其他交易，实际挤出 %s", resNew.EvictedID)
	}
	fmt.Println("\n—— 加费替换：在序号 1 上提交费用 9 的新交易 ——")
	fmt.Printf("已提交新交易（序号 1，费用 9，到期轮次 100）：%s\n", newID)
	fmt.Printf("提交结果关联被替换的旧标识：%s\n", resNew.ReplacedID)

	// 替换后的记录与账户查询：
	// 旧交易仍可按原标识查到，状态 replaced，替代关联指向新交易；
	// 新交易 queued；账户已确认序号仍为 0，待处理列表只有新交易，waiting-pack，缺口 0。
	infoOld, err = n.Tx(oldID)
	check(err)
	infoNew, err := n.Tx(newID)
	check(err)
	if infoOld.Status != consensus.StatusReplaced || infoOld.ReplacedBy != newID ||
		infoOld.BlockHeight != 0 || infoOld.BlockID != "" {
		log.Fatalf("旧交易记录异常：%+v", infoOld)
	}
	if infoNew.Status != consensus.StatusQueued || infoNew.ReplacedBy != "" {
		log.Fatalf("新交易记录异常：%+v", infoNew)
	}
	acct := n.Account(senderPub)
	fmt.Println("\n替换后查询：")
	fmt.Printf("  旧交易 %s：状态=%s，替代关联指向新交易 %s\n",
		short(oldID), infoOld.Status, infoOld.ReplacedBy)
	fmt.Printf("  新交易 %s：状态=%s\n", short(newID), infoNew.Status)
	fmt.Printf("  账户：已确认序号=%d，待处理交易=%d 笔，缺口=%d\n",
		acct.ConfirmedSequence, len(acct.Pending), acct.Gap)
	for _, p := range acct.Pending {
		fmt.Printf("    待处理 %s：状态=%s，说明=%s\n", short(p.ID), p.Status, p.Note)
	}
	fmt.Printf("  当前轮次=%d，确认高度=%d：替换本身不会确认交易或推进账户序号\n",
		n.CurrentRound(), n.Height())

	// 产生本地提议：打包只取各账户当前排队的交易，故交易列表只包含新标识。
	proposal, err := n.Propose()
	check(err)
	if len(proposal.TxIDs) != 1 || proposal.TxIDs[0] != newID {
		log.Fatalf("本地提议应只包含新交易，实际：%v", proposal.TxIDs)
	}
	fmt.Printf("\n本地提议（轮次 %d）：区块 %s\n", proposal.Round, proposal.BlockID)
	for i, id := range proposal.TxIDs {
		fmt.Printf("  打包顺序 %d：%s\n", i+1, id)
	}

	// 提议后查询：新交易进入等待投票；旧记录仍是 replaced，替代关联保持原样。
	infoNew, err = n.Tx(newID)
	check(err)
	infoOld, err = n.Tx(oldID)
	check(err)
	acct = n.Account(senderPub)
	fmt.Println("\n提议后查询：")
	fmt.Printf("  新交易 %s：状态=%s\n", short(newID), infoNew.Status)
	for _, p := range acct.Pending {
		fmt.Printf("  账户待处理 %s：状态=%s，说明=%s\n", short(p.ID), p.Status, p.Note)
	}
	fmt.Printf("  旧交易 %s：状态=%s，替代关联仍指向 %s（保持原样）\n",
		short(oldID), infoOld.Status, short(infoOld.ReplacedBy))
	fmt.Printf("  账户已确认序号=%d：进入提议只是等待投票，同样没有确认交易\n",
		acct.ConfirmedSequence)

	// 误用二（新交易进入提议之后）：再提交同序号、费用更高（12）的交易。
	// 交易已被未决候选引用，替换被 tx-in-proposal 拒绝，冻结的提议与原有
	// 替代关系都不改变。
	txHigher := consensus.NewTransaction(senderKey, 1, []byte("sender: fee 12 after proposal"), 12, 100)
	fmt.Println("\n—— 提议后的误用：对已进入候选的同序号交易再加费 ——")
	expectReject(n, consensus.ReasonProposalLocked, "同序号更高费交易", txHigher)

	frozen, ok := n.Proposal()
	if !ok {
		log.Fatal("拒绝后本地提议应仍可查询")
	}
	infoOld, err = n.Tx(oldID)
	check(err)
	infoNew, err = n.Tx(newID)
	check(err)
	acct = n.Account(senderPub)
	fmt.Println("拒绝后冻结检查：")
	fmt.Printf("  本地提议区块=%s（与拒绝前相同=%v），交易列表 %d 笔：\n",
		frozen.BlockID, frozen.BlockID == proposal.BlockID, len(frozen.TxIDs))
	for i, id := range frozen.TxIDs {
		fmt.Printf("    打包顺序 %d：%s（即新交易=%v）\n", i+1, id, id == newID)
	}
	if frozen.BlockID != proposal.BlockID || len(frozen.TxIDs) != 1 || frozen.TxIDs[0] != newID {
		log.Fatal("冻结的本地提议在拒绝后发生了变化")
	}
	fmt.Printf("  旧交易 %s：状态=%s，替代关联仍指向 %s（原有替代关系不变）\n",
		short(oldID), infoOld.Status, short(infoOld.ReplacedBy))
	if infoOld.Status != consensus.StatusReplaced || infoOld.ReplacedBy != newID {
		log.Fatalf("旧交易的替换关联被改动：%+v", infoOld)
	}
	fmt.Printf("  新交易 %s：状态=%s（仍在等待投票，未被费用 12 的交易替换）\n",
		short(newID), infoNew.Status)
	fmt.Printf("  账户已确认序号=%d，确认高度=%d：全程没有任何交易得到确认\n",
		acct.ConfirmedSequence, n.Height())
}

