301	// proposerAt 是确定性的轮次提议者选择：
302	// 对 seed || round(大端 8 字节) 取 SHA-256，结果对名单人数取模。
303	// 种子、名单顺序与轮次相同时，提议者必然相同。
304	func proposerAt(seed []byte, validators [][]byte, round uint64) []byte {
305		var buf [8]byte
306		binary.BigEndian.PutUint64(buf[:], round)
307		h := sha256.New()
308		h.Write(seed)
309		h.Write(buf[:])
310		sum := h.Sum(nil)
311		idx := binary.BigEndian.Uint64(sum[:8]) % uint64(len(validators))
312		return validators[idx]
313	}
314	
315	// ProposerFor 返回指定轮次的提议者公钥。
316	func (n *Node) ProposerFor(round uint64) []byte {
317		n.mu.Lock()
318		defer n.mu.Unlock()
319		return append([]byte(nil), proposerAt(n.st.Seed, n.st.Validators, round)...)
320	}
321	
322	// CurrentProposer 返回当前轮次的提议者公钥。
323	func (n *Node) CurrentProposer() []byte {
324		return n.ProposerFor(n.CurrentRound())
325	}
